class PDFCore
{
    /**
     * @var string
     */
    public $filename;

    /**
     * @var PDFGenerator
     */
    public $pdf_renderer;

    /**
     * @var PrestaShopCollection|ObjectModel|array
     */
    public $objects;

    /**
     * @var string
     */
    public $template;

    /**
     * @var bool
     */
